using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Newtonsoft.Json.Linq;
public static class Tool013AppearanceProof{
 public static void Run(){var asset="Assets/Tool013Proof/appearance.fbx";AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(var png in Directory.GetFiles("Assets/Tool013Proof","*.png",SearchOption.AllDirectories))AssetDatabase.ImportAsset(png,ImportAssetOptions.ForceSynchronousImport);AssetDatabase.ImportAsset(asset,ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);var root=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(!root)throw new Exception("FBX missing");var materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().ToArray();var sidecar=JObject.Parse(File.ReadAllText("Assets/Tool013Proof/appearance.xhmaterials.json"));int textured=0;foreach(var m in materials){var spec=((JArray)sidecar["colors"]).Single(s=>(string)s["colorId"]==m.name);var expected=spec["baseColor_sRGB"].ToObject<float[]>();for(int i=0;i<3;i++)if(Math.Abs(m.color[i]-expected[i])>.002)throw new Exception("Color mismatch "+m.name);if(Math.Abs(m.GetFloat("_Glossiness")-(1-(float)spec["roughness"]))>.002)throw new Exception("roughness mismatch");if((bool?)spec["baseColorTexture"]==true){if(!m.mainTexture)throw new Exception("Missing PNG "+m.name);textured++;}}if(textured!=3)throw new Exception("Expected three textured precision canvases");var triangles=root.GetComponentsInChildren<MeshFilter>(true).Sum(m=>m.sharedMesh.triangles.Length/3);if(triangles!=36)throw new Exception("Triangle mismatch");File.WriteAllText(Path.GetFullPath("../tool013-tuanjie-receipt.json"),new JObject{["editor"]=Application.unityVersion,["triangles"]=triangles,["materials"]=materials.Length,["textured"]=textured,["status"]="passed"}.ToString());Debug.Log("TOOL013 RECEIVER PASSED");}
}